// ADR-0008 Decision 1 -- structural (contract-shape) validation only. This
// checks the request matches the Finance Inbox Request Contract; it is NOT
// Finance-specific validation (no amount/category/date rules -- those never
// appear in the Request contract at all, and belong to a Handler if they
// ever did).
const req = $json || {};

const KNOWN_CHANNELS = ['slack', 'telegram', 'whatsapp', 'retell', 'web-chat', 'ocr'];
const reasons = [];

function requireNonEmptyString(field) {
  if (typeof req[field] !== 'string' || req[field].trim().length === 0) {
    reasons.push(`Missing/empty required field: ${field}.`);
  }
}

requireNonEmptyString('contractVersion');
requireNonEmptyString('workflowExecutionId');
requireNonEmptyString('workflowName');
requireNonEmptyString('channel');

if (typeof req.rawText !== 'string') {
  reasons.push('rawText must be a string (may be empty).');
}

if (typeof req.channel === 'string' && !KNOWN_CHANNELS.includes(req.channel)) {
  reasons.push(`Unknown channel: ${req.channel}.`);
}

if (!('externalUserId' in req)) reasons.push('Missing externalUserId key.');
if (!('externalMessageId' in req)) reasons.push('Missing externalMessageId key.');
if (!Array.isArray(req.attachments)) reasons.push('attachments must be an array.');

return [{
  json: {
    valid: reasons.length === 0,
    reason: reasons.join(' '),
    contractVersion: req.contractVersion,
    workflowExecutionId: req.workflowExecutionId,
    workflowName: req.workflowName,
    channel: req.channel,
    externalUserId: req.externalUserId ?? null,
    externalMessageId: req.externalMessageId ?? null,
    rawText: typeof req.rawText === 'string' ? req.rawText : '',
    attachments: Array.isArray(req.attachments) ? req.attachments : [],
  },
}];

// The request never reached the classifier -- this is an orchestration-layer
// rejection (malformed envelope), not a Finance business decision, so it
// still returns a fully Response-contract-shaped object (ADR-0008 Decision 2).
const v = $json;

return [{
  json: {
    contractVersion: '1',
    workflowExecutionId: v.workflowExecutionId || 'unknown',
    status: 'error',
    intent: 'UNRECOGNIZED',
    message: 'This request does not match the Finance Inbox Workflow Contract and could not be processed.',
    data: null,
    clarifyingQuestion: null,
  },
}];

// Merges the deterministic classifier's {intent, confidence} output (from
// "Parse Classification Output") with the original request context (from
// "Validate Request Contract"), producing the full record the Intent
// Router and every Handler need. All classification-output validation
// already happened upstream in "Parse Classification Output" -- by the
// time this node runs, $json.intent is guaranteed to be one of the eight
// Intent Catalog values and $json.confidence is guaranteed to be a number
// in [0, 1], so this node does no re-validation, only merging.
const context = $('Validate Request Contract').item.json;

return [{
  json: {
    contractVersion: context.contractVersion,
    workflowExecutionId: context.workflowExecutionId,
    workflowName: context.workflowName,
    channel: context.channel,
    externalUserId: context.externalUserId,
    externalMessageId: context.externalMessageId,
    rawText: context.rawText,
    attachments: context.attachments,
    intent: $json.intent,
    confidence: $json.confidence,
  },
}];

// Orchestration-layer only: if the Execute Workflow call itself failed --
// today, ALWAYS, since no Handler workflow exists yet (Phase 2 explicitly
// does not build one) -- this synthesizes a Response-contract-shaped
// fallback (ADR-0008 Decision 2), using context preserved from "Merge
// Context With Classification" since a failed Execute Workflow call loses
// the original request. This is infrastructural resilience ("the handler
// is unreachable"), never a Finance business decision -- no
// amount/category/budget logic appears here. On success, the Handler's own
// response is returned completely unchanged, per this workflow's stated
// scope.
const context = $('Merge Context With Classification').item.json;
const handlerResult = $json;

if (handlerResult && handlerResult.error) {
  const message = String((handlerResult.error && handlerResult.error.message) || handlerResult.error);
  console.log(`[Return Handler Response] Handler call failed for intent ${context.intent}: ${message}`);

  return [{
    json: {
      contractVersion: '1',
      workflowExecutionId: context.workflowExecutionId,
      status: 'error',
      intent: context.intent,
      message: "Sorry, I couldn't process that just now. Please try again in a moment.",
      data: null,
      clarifyingQuestion: null,
    },
  }];
}

return [{ json: handlerResult }];

// Deterministic classification-output validator. As of the ADR-0014 AI
// Core migration, JSON extraction (fence-stripping, brace-span extraction)
// is AI Core's own job (ai-routing.service.ts's extractJson() -- the exact
// mechanism this node used to do itself pre-migration) -- this node's
// remaining job is unwrapping AI Core's response envelope and re-validating
// the parsed object's business shape (8-value intent enum, confidence in
// [0,1]) as defense-in-depth, since AI Core enforces nothing beyond "is
// this parseable JSON" (see docs/adrs/ADR-0014-finance-ai-core-migration.md).
// Never throws; always returns a value the Intent Router can safely route
// on.
const KNOWN_INTENTS = [
  'CREATE_EXPENSE', 'GET_BUDGET', 'GET_DASHBOARD', 'GET_FINANCE_QUESTION',
  'CREATE_INCOME', 'CREATE_TRANSFER', 'UPLOAD_RECEIPT', 'UNRECOGNIZED',
];
const FALLBACK = { intent: 'UNRECOGNIZED', confidence: 0 };

function isValidClassification(parsed) {
  return (
    parsed !== null &&
    typeof parsed === 'object' &&
    !Array.isArray(parsed) &&
    typeof parsed.intent === 'string' &&
    KNOWN_INTENTS.includes(parsed.intent) &&
    typeof parsed.confidence === 'number' &&
    Number.isFinite(parsed.confidence) &&
    parsed.confidence >= 0 &&
    parsed.confidence <= 1
  );
}

if ($json && $json.error) {
  const message = String(($json.error && $json.error.message) || $json.error);
  console.log(`[Parse Classification Output] AI Core call failed, defaulting to UNRECOGNIZED: ${message}`);
  return [{ json: FALLBACK }];
}

const result = $json && $json.data;

if (!result || result.outcome !== 'VALID') {
  console.log(`[Parse Classification Output] AI Core did not return a valid classification (outcome: ${result && result.outcome}), defaulting to UNRECOGNIZED.`);
  return [{ json: FALLBACK }];
}

const parsed = result.outputJson;

if (isValidClassification(parsed)) {
  return [{ json: { intent: parsed.intent, confidence: parsed.confidence } }];
}

console.log(`[Parse Classification Output] Malformed or invalid classification shape, defaulting to UNRECOGNIZED. Raw: ${String(JSON.stringify(parsed)).slice(0, 300)}`);
return [{ json: FALLBACK }];
